#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the dribble.tf model assets.
#
# Gets TF2's files, rebuilds the first-person viewmodels, builds maps with
# bsp-to-glb, and uploads public/models to the S3 bucket behind the CloudFront CDN that production
# loads models from (VITE_APP_ASSET_URL), then refreshes the CDN's cache.
# Every stage can be skipped. Run it with: npm run assets
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=10

# Run from the repo root, and keep settings in the main checkout's .env so every
# worktree shares them.
cd "$(git rev-parse --show-toplevel)"
ENV_FILE="$(cd "$(dirname "$(git rev-parse --git-common-dir)")" && pwd)/.env"

# ── Helpers ───────────────────────────────────────────────────────────────

have() { command -v "$1" >/dev/null 2>&1; }

# run CMD... prints the command, then runs it; returns its status.
run() {
  printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  "$@"
}

ok()   { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
bad()  { printf '  %s✗%s %s\n' "$RED" "$RESET" "$1"; }

# config_value KEY reads a value from scripts/convert-config.json.
config_value() {
  node -e 'try { const c = require("./scripts/convert-config.json"); process.stdout.write(c[process.argv[1]] || "") } catch {}' "$1"
}

# human_size BYTES
human_size() { awk -v b="$1" 'BEGIN { if (b >= 1048576) printf "%.1f MB", b/1048576; else printf "%.0f KB", b/1024 }'; }

# asset_host: the CDN host from VITE_APP_ASSET_URL (no scheme, no slash).
asset_host() { printf '%s' "$VITE_APP_ASSET_URL" | sed -E 's#^https?://##; s#/.*$##'; }

# discover PROFILE prints "distributionId<TAB>bucket<TAB>originPath" for the
# CloudFront distribution serving asset_host, using that AWS profile.
discover() {
  local profile="$1" json
  json=$(aws cloudfront list-distributions --profile "$profile" --output json 2>/dev/null) || return 1
  printf '%s' "$json" | node -e '
    let data = ""
    process.stdin.on("data", d => (data += d)).on("end", () => {
      const host = process.argv[1]
      const items = JSON.parse(data || "{}").DistributionList?.Items ?? []
      const dist = items.find(d => d.DomainName === host || (d.Aliases?.Items ?? []).includes(host))
      if (!dist) process.exit(1)
      const origins = dist.Origins?.Items ?? []
      const target = dist.DefaultCacheBehavior?.TargetOriginId
      const origin =
        origins.find(o => o.Id === target && /\.s3[.-]/.test(o.DomainName)) ??
        origins.find(o => /\.s3[.-]/.test(o.DomainName))
      if (!origin) process.exit(1)
      const bucket = origin.DomainName.split(/\.s3[.-]/)[0]
      process.stdout.write([dist.Id, bucket, origin.OriginPath || ""].join("\t"))
    })' "$(asset_host)"
}

# s3_prefix: the bucket key prefix CloudFront's origin path adds, with a slash.
s3_prefix() {
  local path="${ASSET_S3_ORIGIN_PATH#/}"
  path="${path%/}"
  if [[ -n "$path" ]]; then printf '%s/' "$path"; fi
}

AWS_READY=0
S3_REGION_ARGS=() # --region for the bucket, once known
UPLOAD_LOCAL=""   # local folder to upload
UPLOAD_REMOTE=""  # where it goes in the bucket
UPLOAD_FILTERS=() # aws s3 sync --exclude/--include, to upload part of the folder
CDN_PATH=""       # the CloudFront path to refresh, e.g. /models/viewmodels/*
UPLOAD_FILTERS=()   # aws s3 sync --exclude/--include, to upload part of a folder
PENDING=0         # files the dry run says would upload
UPLOADED=0
COMMITTED=0

banner "dribble.tf model assets"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Tools"
say "Checking what this machine has. Only the stages you use need their tools."
printf '\n'

MISSING_INSTALLS=()
if have node && [[ -d node_modules ]]; then ok "Node and the project's packages"
elif have node; then bad "the project's packages (npm install)"; MISSING_INSTALLS+=("npm install")
else bad "Node.js: install it from https://nodejs.org, then re-run"; SKIPPED+=("install Node.js")
fi
if have python3 && python3 -I -c "import vpk, vtf2img, PIL" >/dev/null 2>&1; then ok "Python with vpk, vtf2img and Pillow (textures)"
elif have python3; then bad "Python packages vpk, vtf2img, Pillow"; MISSING_INSTALLS+=("python3 -m pip install vpk vtf2img Pillow")
else bad "Python 3: brew install python"; MISSING_INSTALLS+=("brew install python")
fi
if have cargo; then ok "Rust (builds bsp-to-glb, the model converter)"
else bad "Rust: needed to rebuild models; install from https://rustup.rs"; SKIPPED+=("install Rust from https://rustup.rs (only to rebuild models)")
fi
if have depotdownloader; then ok "DepotDownloader (downloads TF2's files)"
else bad "DepotDownloader"; MISSING_INSTALLS+=("brew tap steamre/tools && brew install --cask steamre/tools/depotdownloader")
fi
if have aws; then ok "AWS CLI (uploads)"
else bad "AWS CLI"; MISSING_INSTALLS+=("brew install awscli")
fi

if (( ${#MISSING_INSTALLS[@]} )); then
  printf '\n'
  for cmd in "${MISSING_INSTALLS[@]}"; do
    if confirm "Run: $cmd"; then
      bash -c "$cmd" || { warn "that failed; install it by hand later"; SKIPPED+=("$cmd"); }
    else
      SKIPPED+=("$cmd")
    fi
  done
fi
printf '\n'
pause "Press Enter to continue"

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "TF2's game files"
GAME_DIR="$(config_value game-dir)"
GAME_DIR="${GAME_DIR:-$HOME/tf2-content/tf}"
CONTENT_DIR="$(dirname "$GAME_DIR")"
say "The models are built from TF2's own files in: $CONTENT_DIR"
note "TF2 no longer installs on macOS, so they come from Steam with DepotDownloader."
printf '\n'

DOWNLOAD=0
if [[ -f "$GAME_DIR/tf2_misc_dir.vpk" ]]; then
  ok "found them (last updated $(date -r "$GAME_DIR/tf2_misc_dir.vpk" '+%d %b %Y'))"
  note "Only download again after a TF2 update; it fetches just what changed."
  confirm "Download updates from Steam now?" && DOWNLOAD=1
else
  warn "not found. They're needed to rebuild models (not to upload them)."
  confirm "Download them from Steam now? (~17 GB)" && DOWNLOAD=1
fi

if (( DOWNLOAD )) && ! have depotdownloader; then
  warn "DepotDownloader isn't installed (see stage 1), so skipping the download."
  SKIPPED+=("download TF2's files (install DepotDownloader first)")
elif (( DOWNLOAD )); then
  FILELIST="$HOME/tf2-filelist.txt"
  if [[ ! -f "$FILELIST" ]]; then
    printf '%s\n' 'regex:^tf/tf2_(misc|textures)_.*\.vpk$' 'regex:^hl2/hl2_(misc|textures)_.*\.vpk$' \
      'regex:^tf/scripts/items/' 'tf/gameinfo.txt' > "$FILELIST"
    ok "wrote the list of files to download: $FILELIST"
  fi
  ask TF2_STEAM_USERNAME "Your Steam login name (not your display name):"
  write_env TF2_STEAM_USERNAME "$TF2_STEAM_USERNAME"
  printf '\n'
  step "DepotDownloader asks for your Steam password itself (this wizard never sees it)."
  step "Then approve the sign-in in the Steam app on your phone."
  note "If it says the account has no access to app 440, add Team Fortress 2 to your"
  note "library on its Steam store page (it's free), then run this stage again."
  printf '\n'
  if run depotdownloader -app 440 -os windows -filelist "$FILELIST" -dir "$CONTENT_DIR" \
      -username "$TF2_STEAM_USERNAME" -remember-password; then
    ok "download finished"
  else
    warn "the download failed; scroll up for DepotDownloader's error"
    SKIPPED+=("download TF2's files")
  fi
fi

if [[ -f "$GAME_DIR/tf2_misc_dir.vpk" ]]; then
  if ! python3 -I -c "import vpk" >/dev/null 2>&1; then
    note "(install the Python packages from stage 1 to check the files)"
  elif python3 -I -c "
import sys, vpk
names = set(vpk.open(sys.argv[1]))
sys.exit(0 if {'models/weapons/c_models/c_soldier_arms.mdl', 'models/buildables/sentry1.mdl'} <= names else 1)
" "$GAME_DIR/tf2_misc_dir.vpk" 2>/dev/null; then
    ok "the files check out"
  else
    warn "tf2_misc_dir.vpk is there but doesn't have the expected models"
  fi
  if [[ "$(config_value game-dir)" != "$CONTENT_DIR/tf" || "$(config_value hl2-dir)" != "$CONTENT_DIR/hl2" ]]; then
    if confirm "Point scripts/convert-config.json at $CONTENT_DIR?"; then
      node -e '
        const fs = require("fs"), file = "scripts/convert-config.json"
        const c = fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, "utf8")) : {}
        c["game-dir"] = process.argv[1] + "/tf"; c["hl2-dir"] = process.argv[1] + "/hl2"
        fs.writeFileSync(file, JSON.stringify(c, null, 2) + "\n")' "$CONTENT_DIR"
      ok "updated scripts/convert-config.json"
    fi
  fi
fi
printf '\n'
pause "Press Enter to continue"

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Rebuild the viewmodels"
say "Rebuilds public/models/viewmodels from TF2's files: the first-person arms,"
say "their animations and every weapon. It also rebuilds the engineer's buildings"
say "in public/models/buildings."
note "Only needed after a TF2 update or a change to scripts/viewmodels/. Models that"
note "haven't changed are skipped, so a rebuild usually takes a couple of minutes."
printf '\n'

if [[ ! -f "$GAME_DIR/tf2_misc_dir.vpk" ]]; then
  warn "TF2's files aren't there (stage 2), so there's nothing to build from. Skipping."
elif confirm "Rebuild the viewmodels now?"; then
  FORCE=()
  confirm "Rebuild every model from scratch (~8 min) instead of only changed ones?" && FORCE=(-- --force)
  if run npm run build:viewmodels "${FORCE[@]+"${FORCE[@]}"}"; then
    ok "built"
  else
    warn "the build failed; scroll up for the error"
    SKIPPED+=("rebuild the viewmodels (npm run build:viewmodels)")
  fi

  CHANGED=$(git status --porcelain -- public/models/viewmodels public/models/buildings | wc -l | tr -d ' ')
  if (( CHANGED > 0 )); then
    printf '\n'
    say "$CHANGED file(s) changed in public/models/viewmodels and public/models/buildings."
    BRANCH=$(git branch --show-current)
    if confirm "Commit them on branch '$BRANCH'?"; then
      git add public/models/viewmodels public/models/buildings
      if git commit -q -m "Rebuild the viewmodels"; then
        ok "committed on $BRANCH"
        COMMITTED=1
      else
        warn "the commit failed"
      fi
    else
      SKIPPED+=("commit the rebuilt models in public/models/viewmodels and public/models/buildings")
    fi
  else
    ok "nothing changed"
  fi
fi
printf '\n'
pause "Press Enter to continue"

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Build maps"
say "Builds maps from their BSPs with bsp-to-glb into public/models/maps (plus the"
say "prop models and skies they share), listed in public/models/maps/index.json."
note "A map name downloads its BSP from serveme.tf; maps that haven't changed are"
note "skipped. A new map takes a few minutes, mostly its prop textures."
printf '\n'

MAPS_INDEX=public/models/maps/index.json
BUILT_MAPS=""
[[ -f "$MAPS_INDEX" ]] && BUILT_MAPS=$(node -e 'process.stdout.write(Object.keys(require("./" + process.argv[1]).maps).join(" "))' "$MAPS_INDEX")
[[ -n "$BUILT_MAPS" ]] && note "Built so far: $BUILT_MAPS"
# Built maps aren't in git (only the index is), so a fresh checkout fetches them from the CDN
# before building more or uploading.
MISSING_MAPS=""
for map in $BUILT_MAPS; do [[ -f "public/models/maps/$map/map.json" ]] || MISSING_MAPS="$MISSING_MAPS $map"; done
if [[ -n "$MISSING_MAPS" ]]; then
  warn "Not in this checkout yet:$MISSING_MAPS"
  if confirm "Fetch them from the CDN (npm run maps:pull)?"; then
    run npm run maps:pull || warn "some maps weren't fetched; scroll up for why"
  fi
fi
if [[ ! -f "$GAME_DIR/tf2_misc_dir.vpk" ]]; then
  warn "TF2's files aren't there (stage 2), so there's nothing to build from. Skipping."
elif confirm "Build maps now?"; then
  ask MAPS_TO_BUILD "Map names, space-separated (Enter rebuilds the ones above):"
  MAPS_TO_BUILD="${MAPS_TO_BUILD:-$BUILT_MAPS}"
  if [[ -z "$MAPS_TO_BUILD" ]]; then
    warn "no maps named, skipping"
  # shellcheck disable=SC2086 # one argument per map name
  elif run npm run build:maps -- $MAPS_TO_BUILD; then
    ok "built"
  else
    warn "some maps failed; scroll up for the errors"
    SKIPPED+=("build maps (npm run build:maps -- <map>...)")
  fi
fi
printf '\n'
pause "Press Enter to continue"

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "AWS login"
say "Production loads models from your CloudFront CDN, which serves an S3 bucket."
say "Finding an AWS login that can see it."
printf '\n'

if ! have aws; then
  warn "The AWS CLI isn't installed (stage 1), so the upload stages will be skipped."
  SKIPPED+=("install the AWS CLI (brew install awscli), then upload")
else
  VITE_APP_ASSET_URL="$(_existing VITE_APP_ASSET_URL || true)"
  if [[ -z "$VITE_APP_ASSET_URL" ]]; then
    step "Your .env has no VITE_APP_ASSET_URL: the CDN address production uses,"
    step "like https://dxxxxxxxxxxxx.cloudfront.net (it's also in Vercel's env settings)."
    ask VITE_APP_ASSET_URL "CDN address:"
    write_env VITE_APP_ASSET_URL "$VITE_APP_ASSET_URL"
  fi
  note "CDN: $(asset_host)"
  printf '\n'

  # The saved profile first, then every profile on this machine.
  SAVED_PROFILE="$(_existing ASSET_AWS_PROFILE || true)"
  CANDIDATES=()
  [[ -n "$SAVED_PROFILE" ]] && CANDIDATES+=("$SAVED_PROFILE")
  while IFS= read -r p; do
    [[ -n "$p" && "$p" != "$SAVED_PROFILE" ]] && CANDIDATES+=("$p")
  done < <(aws configure list-profiles 2>/dev/null)

  try_profiles() {
    local p found
    for p in "$@"; do
      if ! aws sts get-caller-identity --profile "$p" >/dev/null 2>&1; then
        bad "$p: not logged in (expired or invalid)"
        continue
      fi
      if found=$(discover "$p"); then
        ok "$p: can see the CDN"
        ASSET_AWS_PROFILE="$p"
        IFS=$'\t' read -r FOUND_DIST FOUND_BUCKET FOUND_ORIGIN_PATH <<< "$found"
        return 0
      fi
      bad "$p: logged in, but can't see this CDN"
    done
    return 1
  }

  if (( ${#CANDIDATES[@]} )) && try_profiles "${CANDIDATES[@]}"; then
    AWS_READY=1
  fi

  while (( ! AWS_READY )); do
    printf '\n'
    warn "None of your AWS logins can see the CDN."
    say "If one above is expired and you know how to refresh it, do that, then retry."
    say "Otherwise, set up a 'dribble' login with an access key:"
    step "In the AWS console for the account that owns the CDN: IAM → Users."
    step "Create user (e.g. 'dribble-assets') → Attach policies directly →"
    step "  tick AmazonS3FullAccess and CloudFrontFullAccess → Create user."
    step "Open the user → Security credentials → Create access key →"
    step "  'Command Line Interface (CLI)' → Create access key."
    step "Leave that page open: the next prompts ask for the key ID and secret."
    note "(The keys go into the AWS CLI's own prompts, not this wizard.)"
    printf '\n'
    printf '  %s1%s set up the dribble login  %s2%s retry  %s3%s type a profile name  %s4%s skip uploading\n' \
      "$BOLD" "$RESET" "$BOLD" "$RESET" "$BOLD" "$RESET" "$BOLD" "$RESET"
    printf '  %sChoose 1-4:%s ' "$BOLD" "$RESET"
    read -r choice || true
    case "$choice" in
      1)
        open_url "https://console.aws.amazon.com/iam/home#/users"
        pause "Press Enter once the access key page is showing"
        say "Paste the key ID and secret when asked; region: us-east-1, output: json."
        run aws configure --profile dribble || true
        try_profiles dribble && AWS_READY=1
        ;;
      2)
        try_profiles "${CANDIDATES[@]+"${CANDIDATES[@]}"}" dribble && AWS_READY=1
        ;;
      3)
        ask TYPED_PROFILE "Profile name:"
        [[ -n "$TYPED_PROFILE" ]] && try_profiles "$TYPED_PROFILE" && AWS_READY=1
        ;;
      4)
        SKIPPED+=("upload the models (no AWS login could see the CDN)")
        break
        ;;
    esac
  done

  if (( AWS_READY )); then
    write_env ASSET_AWS_PROFILE "$ASSET_AWS_PROFILE"
  fi
fi
printf '\n'
pause "Press Enter to continue"

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "The bucket and the CDN"
if (( ! AWS_READY )); then
  warn "No AWS login (stage 5), so skipping."
else
  say "Found from your CloudFront settings:"
  note "CloudFront distribution: $FOUND_DIST"
  note "S3 bucket:               $FOUND_BUCKET"
  [[ -n "$FOUND_ORIGIN_PATH" ]] && note "Origin path:             $FOUND_ORIGIN_PATH"
  ASSET_CLOUDFRONT_DISTRIBUTION_ID="$FOUND_DIST"
  ASSET_S3_BUCKET="$FOUND_BUCKET"
  ASSET_S3_ORIGIN_PATH="$FOUND_ORIGIN_PATH"
  printf '\n'
  write_env ASSET_CLOUDFRONT_DISTRIBUTION_ID "$ASSET_CLOUDFRONT_DISTRIBUTION_ID"
  write_env ASSET_S3_BUCKET "$ASSET_S3_BUCKET"
  write_env ASSET_S3_ORIGIN_PATH "$ASSET_S3_ORIGIN_PATH"

  # S3 wants requests in the bucket's own region (null means us-east-1).
  if ASSET_S3_REGION=$(aws s3api get-bucket-location --profile "$ASSET_AWS_PROFILE" \
      --bucket "$ASSET_S3_BUCKET" --query LocationConstraint --output text 2>/dev/null); then
    [[ -z "$ASSET_S3_REGION" || "$ASSET_S3_REGION" == "None" || "$ASSET_S3_REGION" == "null" ]] && ASSET_S3_REGION=us-east-1
    S3_REGION_ARGS=(--region "$ASSET_S3_REGION")
    note "Bucket region:           $ASSET_S3_REGION"
    write_env ASSET_S3_REGION "$ASSET_S3_REGION"
  fi

  PROBE="$(s3_prefix)models/players/soldier_red.glb"
  if aws s3api head-object --profile "$ASSET_AWS_PROFILE" "${S3_REGION_ARGS[@]+"${S3_REGION_ARGS[@]}"}" --bucket "$ASSET_S3_BUCKET" --key "$PROBE" >/dev/null 2>&1; then
    ok "the bucket has the existing models (s3://$ASSET_S3_BUCKET/$PROBE)"
  else
    warn "couldn't read s3://$ASSET_S3_BUCKET/$PROBE: the login may lack S3 access"
    warn "or the models live somewhere else. Skipping the upload to be safe."
    AWS_READY=0
    SKIPPED+=("upload the models (couldn't read the bucket)")
  fi
fi
printf '\n'
pause "Press Enter to continue"

# ── Stage 7 ───────────────────────────────────────────────────────────────
stage "Choose what to upload"
if (( ! AWS_READY )); then
  warn "No AWS access (stages 5-6), so skipping."
else
  printf '  %s1%s viewmodels and buildings only (public/models/viewmodels, public/models/buildings)\n' "$BOLD" "$RESET"
  printf '  %s2%s built maps only (public/models/maps, props and skybox)\n' "$BOLD" "$RESET"
  printf '  %s3%s everything in public/models (maps, players, projectiles, skyboxes, viewmodels, buildings)\n' "$BOLD" "$RESET"
  printf '  %s4%s nothing\n' "$BOLD" "$RESET"
  printf '  %sChoose 1-4:%s ' "$BOLD" "$RESET"
  read -r choice || true
  case "$choice" in
    1)
      UPLOAD_LOCAL="public/models"; UPLOAD_REMOTE="models"; CDN_PATH="/models/*"
      UPLOAD_FILTERS=(--exclude "*" --include "viewmodels/*" --include "buildings/*")
      ;;
    2)
      # Safe before the site runs this code: older code never reads maps/index.json, and every
      # other file is new (content-hashed names). Only index.json and map.json get replaced.
      UPLOAD_LOCAL="public/models"; UPLOAD_REMOTE="models"; CDN_PATH="/models/maps/*"
      UPLOAD_FILTERS=(--exclude "*" --include "maps/index.json" --include "maps/*/map.json" \
        --include "maps/*/*.*.*" --include "maps/*/textures/*" --include "maps/*/lightmaps/*" \
        --include "props/*" --include "skybox/*/*.webp")
      ;;
    3)
      printf '\n'
      warn "Map files are only read correctly by the code that made them. Upload"
      warn "everything only once the site (dribble.tf) runs the code from this branch,"
      warn "or older, smaller-but-different maps may fail to load in production."
      if confirm "Is the live site running this code?"; then
        UPLOAD_LOCAL="public/models"; UPLOAD_REMOTE="models"; CDN_PATH="/models/*"
      else
        say "Then use 1 (viewmodels and buildings only) for now."
      fi
      ;;
  esac

  if [[ -n "$UPLOAD_LOCAL" ]]; then
    DEST="s3://$ASSET_S3_BUCKET/$(s3_prefix)$UPLOAD_REMOTE"
    printf '\n'
    say "Comparing $UPLOAD_LOCAL with $DEST ..."
    DRY=$(aws s3 sync "$UPLOAD_LOCAL" "$DEST" --profile "$ASSET_AWS_PROFILE" "${S3_REGION_ARGS[@]+"${S3_REGION_ARGS[@]}"}" --dryrun "${UPLOAD_FILTERS[@]+"${UPLOAD_FILTERS[@]}"}" --exclude "*.DS_Store" 2>&1) || {
      warn "the comparison failed:"; printf '%s\n' "$DRY" | tail -5; DRY=""; UPLOAD_LOCAL=""
    }
    BYTES=0
    while IFS= read -r line; do
      [[ "$line" == "(dryrun) upload: "* ]] || continue
      file="${line#(dryrun) upload: }"
      file="${file%% to s3://*}"
      PENDING=$((PENDING + 1))
      BYTES=$((BYTES + $(wc -c < "$file")))
    done <<< "$DRY"
    if [[ -n "$UPLOAD_LOCAL" ]]; then
      if (( PENDING )); then ok "$PENDING file(s) to upload, $(human_size "$BYTES")"
      else ok "the CDN already has all of it; nothing to upload"; fi
    fi
  fi
fi
printf '\n'
pause "Press Enter to continue"

# ── Stage 8 ───────────────────────────────────────────────────────────────
stage "Upload"
if (( ! AWS_READY )) || [[ -z "$UPLOAD_LOCAL" ]] || (( ! PENDING )); then
  note "Nothing to upload, skipping."
elif confirm "Upload $PENDING file(s) to $DEST?"; then
  if run aws s3 sync "$UPLOAD_LOCAL" "$DEST" --profile "$ASSET_AWS_PROFILE" "${S3_REGION_ARGS[@]+"${S3_REGION_ARGS[@]}"}" "${UPLOAD_FILTERS[@]+"${UPLOAD_FILTERS[@]}"}" --exclude "*.DS_Store" --only-show-errors; then
    ok "uploaded $PENDING file(s)"
    UPLOADED=1
  else
    warn "the upload failed; scroll up for the error. Re-running uploads only what's missing."
    SKIPPED+=("finish the upload (re-run this wizard)")
  fi
else
  SKIPPED+=("upload $UPLOAD_LOCAL")
fi
printf '\n'
pause "Press Enter to continue"

# ── Stage 9 ───────────────────────────────────────────────────────────────
stage "Refresh the CDN's cache"
if (( ! UPLOADED )); then
  note "Nothing was uploaded, skipping."
else
  say "CloudFront keeps copies of files for up to a day. Replaced files need its"
  say "cache cleared, or people keep getting the old ones. New files don't."
  printf '\n'
  if confirm "Clear the CDN's cache for $CDN_PATH?"; then
    if INVALIDATION=$(aws cloudfront create-invalidation --profile "$ASSET_AWS_PROFILE" \
        --distribution-id "$ASSET_CLOUDFRONT_DISTRIBUTION_ID" --paths "$CDN_PATH" \
        --query Invalidation.Id --output text); then
      ok "started ($INVALIDATION); it usually takes a few minutes"
      if confirm "Wait here until it's done?"; then
        run aws cloudfront wait invalidation-completed --profile "$ASSET_AWS_PROFILE" \
          --distribution-id "$ASSET_CLOUDFRONT_DISTRIBUTION_ID" --id "$INVALIDATION" && ok "done"
      fi
    else
      warn "couldn't start it; the login may lack CloudFront access"
      SKIPPED+=("clear the CloudFront cache for $CDN_PATH")
    fi
  else
    SKIPPED+=("clear the CloudFront cache for $CDN_PATH (replaced files may stay stale for a day)")
  fi
fi
printf '\n'
pause "Press Enter to continue"

# ── Stage 10 ──────────────────────────────────────────────────────────────
stage "Check the CDN"
VITE_APP_ASSET_URL="${VITE_APP_ASSET_URL:-$(_existing VITE_APP_ASSET_URL || true)}"
if [[ -z "$VITE_APP_ASSET_URL" ]]; then
  note "No CDN address saved, skipping."
else
  BASE="${VITE_APP_ASSET_URL%/}"
  check() {
    local path="$1" code
    code=$(curl -s -o /dev/null -w '%{http_code}' "$BASE/$path" || true)
    if [[ "$code" == "200" ]]; then ok "$path"; else bad "$path (HTTP $code)"; fi
  }
  say "Fetching from $BASE:"
  check "models/viewmodels/manifest.json"
  check "models/viewmodels/arms/soldier.glb"
  check "models/buildings/sentry1_red.glb"
  check "models/players/soldier_red.glb"
  [[ -f public/models/maps/index.json ]] && check "models/maps/index.json"
  MAP=public/models/maps/cp_snakewater_final1/textured_compressed.glb
  if [[ -f "$MAP" ]]; then
    REMOTE_SIZE=$(curl -sI "$BASE/${MAP#public/}" | awk 'tolower($1) == "content-length:" { print $2 }' | tr -d '\r')
    LOCAL_SIZE=$(wc -c < "$MAP" | tr -d ' ')
    if [[ "$REMOTE_SIZE" == "$LOCAL_SIZE" ]]; then ok "maps match this checkout (cp_snakewater)"
    else note "maps differ from this checkout (cp_snakewater: CDN ${REMOTE_SIZE:-?} bytes, here $LOCAL_SIZE)"; fi
  fi
  note "A 403 means the file isn't in the bucket yet."
fi
printf '\n'
pause "Press Enter to finish"

finish
(( COMMITTED )) && note "Push the branch and merge it, so the site has the rebuilt models in git too."
(( UPLOADED )) && note "Uploaded: $UPLOAD_LOCAL → $DEST"
printf '\n'
